 return dict(ticker='MRVL',company='Marvell Technology, Inc.',currency='USD',scenario='base',sourceScenario=name,ratioUnit='decimal',forecastHorizonYears=15,incrementalResearch=id,valuationTiming={'discountOrigin':'2026-08-01'},anchor={'period':'FY2027 full-year reference','fiscalEnd':None,'kind':'analyst_forecast','classification':'Mixed actual / forecast reference','revenue':r['annual_revenue_scale'],'EBIT':None,'firstModeledPeriod':'FY2028','fiscalCalendarCaution':'Fixed source H2 FY2027 plus fifteen full fiscal years; not calendar years.'},openingStub={'period':'H2 FY2027','durationYears':.5,'revenue':r['revenue'],'operatingMargin':r['expensed_rd_economic_margin'],'taxRate':r['tax_rate'],'reinvestment':r['nonresearch_reinvestment'],'wacc':r['period_wacc'],'sourceRow':r},annual=[dict(year=i+1,period='FY'+str(r['fiscal_year']),revenue=r['revenue'],operatingMargin=r['expensed_rd_economic_margin'],taxRate=r['tax_rate'],reinvestment=r['nonresearch_reinvestment'],wacc=r['period_wacc'],sourceRow=r) for i,r in enumerate(x['rows'][1:])],terminal={'growth':t['growth'],'operatingMargin':t['expensed_rd_nopat']/t['revenue']/(1-x['rows'][-1]['tax_rate']),'taxRate':x['rows'][-1]['tax_rate'],'ROIC':t['incremental_economic_roic'],'wacc':t['wacc']},mrvlFundingPolicy={'otherNWCRatio':.30 if name=='downside' else .25,'terminalResearchRatio':t['research_spend']/t['revenue']},boundedModelGaps=[pairs[k][0] for k in ['scope','funding','claimLimits','uncertainty']])
